persuasion_principles:
{
  "Reciprocity": {"Explanation": "The email asks the receiver to take a corrective action (review recent activity and click here to opt out or change notification settings) in return for receiving the email and the implied favor of being protected by PayPal."},
  "Scarcity": {"Explanation": "The email creates a sense of urgency by implying that the receiver's account has been compromised and needs to be reviewed immediately."},
  "Authority": {"Explanation": "The email displays credibility through the recognized institution 'PayPal' and its team, which is likely to be trusted by the receiver."},
  "Commitment/Consistency": {"Explanation": "The email references prior behavior (assuming the receiver has a PayPal account and has signed in before) to push the receiver to take corrective action."},
  "Liking": {"Explanation": "The email does not explicitly use familiarity, flattery, or personalization to build trust or rapport."},
  "Social proof": {"Explanation": "The email does not explicitly reference other people's participation or endorsement."}
}

